def bounds(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if not grid[r][c] or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    y,x=q.pop();cells.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     ny,nx=y+dy,x+dx
     if 0<=ny<h and 0<=nx<w and grid[ny][nx] and (ny,nx) not in seen:seen.add((ny,nx));q.append((ny,nx))
   out.append((len(cells),min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
 return sorted(out,reverse=True)
